    async function locked(fn) { if (busy || c.isWriting()) return; busy = true; c.setWriting(true); try { return await fn(); } finally { busy = false; c.setWriting(false); } }
    function remember(controller, action, result) {
      if (action === 'PostReceipt') { state.lastReceiptData = result; state.lastReceipt = result.documentId; state.drafts = []; }
      if (action === 'PostOperation') state.lastOperation = result;
      if (action === 'PostPreparation') state.lastPreparation = result;
      if (action === 'PostServe') { state.lastServe = result; history.replaceState(null, '', location.pathname + location.search + '#serve'); }
      if (action === 'CreateSnapshot') history.replaceState(null, '', location.pathname + location.search + '#count?document=' + encodeURIComponent(result.document.id));
    }
    async function saved(controller, action, body, journal = false, after) { return locked(async () => { const result = journal ? await writes.post(controller, action, body) : await api.request(controller, action, { body }); remember(controller, action, result); if (after) after(result); await c.render(true); toast('已保存'); return result; }); }
